import radarConfig from '../data/radar-config.json' with { type: 'json' };
import type { Quadrant, QuadrantConfig, Ring, RingConfig } from '../types/radar';

// Generated by `radar build` from .radar.yaml.
export const RADAR_VERSION: string = radarConfig.version;

const PALETTE = ['#2da44e', '#0969da', '#bf8700', '#cf222e'];

export const QUADRANT_ORDER: Quadrant[] = radarConfig.quadrants.map((q) => q.slug);

// Quadrant i spans a quarter turn clockwise from 12 o'clock + i * 90°
// (0 = top-right, 1 = bottom-right, 2 = bottom-left, 3 = top-left).
export const QUADRANT_CONFIGS: Record<Quadrant, QuadrantConfig> = Object.fromEntries(
  radarConfig.quadrants.map((q, i) => {
    const startAngle = -Math.PI / 2 + (i * Math.PI) / 2;
    return [q.slug, { label: q.label, startAngle, endAngle: startAngle + Math.PI / 2, color: PALETTE[i] }];
  }),
);

const RING_RADII: [number, number][] = [
  [0, 150],
  [150, 275],
  [275, 375],
  [375, 475],
];

export const RING_ORDER: Ring[] = radarConfig.rings.map((r) => r.slug);

export const RING_CONFIGS: RingConfig[] = radarConfig.rings.map((r, i) => ({
  label: r.label,
  innerRadius: RING_RADII[i][0],
  outerRadius: RING_RADII[i][1],
}));

export const RING_LABELS: Record<Ring, string> = Object.fromEntries(radarConfig.rings.map((r) => [r.slug, r.label]));

export const RING_COLORS: Record<Ring, string> = Object.fromEntries(radarConfig.rings.map((r, i) => [r.slug, PALETTE[i]]));

export const RADAR_RADIUS = RING_RADII[RING_RADII.length - 1][1];

// Half-width of the full view: the outer ring plus room for its stroke.
const EXTENT = RADAR_RADIUS + 15;

export interface ViewBounds {
  x: number;
  y: number;
  size: number;
}

export const FULL_BOUNDS: ViewBounds = { x: -EXTENT, y: -EXTENT, size: EXTENT * 2 };

/** The square of the view that contains one quadrant, derived from its angles. */
export function quadrantBounds(quadrant: Quadrant): ViewBounds {
  const { startAngle, endAngle } = QUADRANT_CONFIGS[quadrant];
  const mid = (startAngle + endAngle) / 2;
  return {
    x: Math.cos(mid) > 0 ? 0 : -EXTENT,
    y: Math.sin(mid) > 0 ? 0 : -EXTENT,
    size: EXTENT,
  };
}

export function toViewBox({ x, y, size }: ViewBounds): string {
  return `${x} ${y} ${size} ${size}`;
}
